import os
import html
from typing import Iterable, Optional, Sequence, Union

import requests


DEEPL_API_URL = "https://api-free.deepl.com/v2/translate"
DEEPL_API_URL_PRO = "https://api.deepl.com/v2/translate"


class DeepLTranslationError(Exception):
    pass


def _normalize_target_lang(target_lang: str) -> str:
    if not target_lang or not target_lang.strip():
        raise ValueError("target_lang is required")
    return target_lang.strip().upper()


def _normalize_source_lang(source_lang: Optional[str]) -> Optional[str]:
    if source_lang is None:
        return None
    source_lang = source_lang.strip()
    return source_lang.upper() if source_lang else None


def _coerce_texts(text: Union[str, Sequence[str]]) -> list[str]:
    if isinstance(text, str):
        return [text]
    if not isinstance(text, Iterable):
        raise TypeError("text must be a string or a sequence of strings")
    texts = list(text)
    if not texts:
        return []
    if not all(isinstance(t, str) for t in texts):
        raise TypeError("all items in text sequence must be strings")
    return texts


def translate_markup(
    text: Union[str, Sequence[str]],
    target_lang: str,
    source_lang: Optional[str] = None,
    *,
    auth_key: Optional[str] = None,
    tag_handling: str = "html",
    split_sentences: Optional[str] = None,
    preserve_formatting: bool = True,
    formality: Optional[str] = None,
    glossary_id: Optional[str] = None,
    context: Optional[str] = None,
    use_pro: Optional[bool] = None,
    timeout: float = 30.0,
) -> Union[str, list[str]]:
    texts = _coerce_texts(text)
    if not texts:
        return [] if not isinstance(text, str) else ""

    key = auth_key or os.environ.get("DEEPL_AUTH_KEY")
    if not key:
        raise ValueError("DeepL auth key is required via auth_key or DEEPL_AUTH_KEY")

    api_url = DEEPL_API_URL_PRO if use_pro else DEEPL_API_URL
    if use_pro is None:
        api_url = DEEPL_API_URL_PRO if key.endswith(":fx") else DEEPL_API_URL

    data: list[tuple[str, str]] = []
    for item in texts:
        data.append(("text", item))

    data.append(("target_lang", _normalize_target_lang(target_lang)))
    normalized_source = _normalize_source_lang(source_lang)
    if normalized_source:
        data.append(("source_lang", normalized_source))

    if tag_handling:
        data.append(("tag_handling", tag_handling))
    if split_sentences:
        data.append(("split_sentences", split_sentences))
    if preserve_formatting is not None:
        data.append(("preserve_formatting", "1" if preserve_formatting else "0"))
    if formality:
        data.append(("formality", formality))
    if glossary_id:
        data.append(("glossary_id", glossary_id))
    if context:
        data.append(("context", context))

    headers = {
        "Authorization": f"DeepL-Auth-Key {key}",
        "Accept": "application/json",
    }

    response = requests.post(api_url, headers=headers, data=data, timeout=timeout)
    if response.status_code >= 400:
        try:
            payload = response.json()
        except Exception:
            payload = response.text
        raise DeepLTranslationError(f"DeepL API error {response.status_code}: {payload}")

    payload = response.json()
    translations = payload.get("translations")
    if not isinstance(translations, list):
        raise DeepLTranslationError(f"Unexpected DeepL response: {payload}")

    results = [item.get("text", "") for item in translations]
    return results[0] if isinstance(text, str) else results


def translate_html(
    html_text: Union[str, Sequence[str]],
    target_lang: str,
    source_lang: Optional[str] = None,
    **kwargs,
) -> Union[str, list[str]]:
    return translate_markup(
        html_text,
        target_lang=target_lang,
        source_lang=source_lang,
        tag_handling="html",
        **kwargs,
    )


def translate_xml(
    xml_text: Union[str, Sequence[str]],
    target_lang: str,
    source_lang: Optional[str] = None,
    *,
    outline_detection: Optional[bool] = None,
    splitting_tags: Optional[Sequence[str]] = None,
    non_splitting_tags: Optional[Sequence[str]] = None,
    ignore_tags: Optional[Sequence[str]] = None,
    auth_key: Optional[str] = None,
    use_pro: Optional[bool] = None,
    timeout: float = 30.0,
    **kwargs,
) -> Union[str, list[str]]:
    texts = _coerce_texts(xml_text)
    if not texts:
        return [] if not isinstance(xml_text, str) else ""

    key = auth_key or os.environ.get("DEEPL_AUTH_KEY")
    if not key:
        raise ValueError("DeepL auth key is required via auth_key or DEEPL_AUTH_KEY")

    api_url = DEEPL_API_URL_PRO if use_pro else DEEPL_API_URL
    if use_pro is None:
        api_url = DEEPL_API_URL_PRO if key.endswith(":fx") else DEEPL_API_URL

    data: list[tuple[str, str]] = []
    for item in texts:
        data.append(("text", item))

    data.append(("target_lang", _normalize_target_lang(target_lang)))
    normalized_source = _normalize_source_lang(source_lang)
    if normalized_source:
        data.append(("source_lang", normalized_source))

    data.append(("tag_handling", "xml"))

    if outline_detection is not None:
        data.append(("outline_detection", "1" if outline_detection else "0"))

    for tag in splitting_tags or ():
        data.append(("splitting_tags", tag))
    for tag in non_splitting_tags or ():
        data.append(("non_splitting_tags", tag))
    for tag in ignore_tags or ():
        data.append(("ignore_tags", tag))

    for key_name, value in kwargs.items():
        if value is None:
            continue
        if isinstance(value, bool):
            data.append((key_name, "1" if value else "0"))
        else:
            data.append((key_name, str(value)))

    headers = {
        "Authorization": f"DeepL-Auth-Key {key}",
        "Accept": "application/json",
    }

    response = requests.post(api_url, headers=headers, data=data, timeout=timeout)
    if response.status_code >= 400:
        try:
            payload = response.json()
        except Exception:
            payload = response.text
        raise DeepLTranslationError(f"DeepL API error {response.status_code}: {payload}")

    payload = response.json()
    translations = payload.get("translations")
    if not isinstance(translations, list):
        raise DeepLTranslationError(f"Unexpected DeepL response: {payload}")

    results = [item.get("text", "") for item in translations]
    return results[0] if isinstance(xml_text, str) else results


def translate_plaintext_as_safe_html(
    text: str,
    target_lang: str,
    source_lang: Optional[str] = None,
    *,
    auth_key: Optional[str] = None,
    use_pro: Optional[bool] = None,
    timeout: float = 30.0,
) -> str:
    escaped = f"<div>{html.escape(text)}</div>"
    translated = translate_html(
        escaped,
        target_lang=target_lang,
        source_lang=source_lang,
        auth_key=auth_key,
        use_pro=use_pro,
        timeout=timeout,
    )
    if translated.startswith("<div>") and translated.endswith("</div>"):
        return translated[5:-6]
    return translated
